# ============ MT4 Order Helper Functions ============

class MT4OrderType:
    """MT4 Order Types (replaces OANDA order types)"""
    MARKET = "MARKET"
    LIMIT = "LIMIT"
    STOP = "STOP"
    STOP_LIMIT = "STOP_LIMIT"


class MT4TimeInForce:
    """MT4 Time in Force (replaces OANDA time in force)"""
    GTC = "GTC"  # Good Till Cancelled
    DAY = "DAY"  # Day order
    IOC = "IOC"  # Immediate or Cancel
    FOK = "FOK"  # Fill or Kill


class MT4OrderPositionFill:
    """MT4 Position Fill Types (replaces OANDA position fill)"""
    DEFAULT = "DEFAULT"
    OPEN_ONLY = "OPEN_ONLY"
    REDUCE_FIRST = "REDUCE_FIRST"
    REDUCE_ONLY = "REDUCE_ONLY"


def create_market_order(instrument, units, stop_loss=None, take_profit=None):
    """
    Helper function to create a market order data structure
    
    Parameters
    ----------
    instrument : str
        Instrument symbol (e.g., 'EURUSD')
    units : int
        Positive for BUY, negative for SELL
    stop_loss : float, optional
        Stop loss price
    take_profit : float, optional
        Take profit price
    
    Returns
    -------
    dict
        Order data structure
    """
    order = {
        "type": MT4OrderType.MARKET,
        "instrument": instrument,
        "units": str(units)
    }
    
    if stop_loss:
        order["stopLossOnFill"] = stop_loss
    if take_profit:
        order["takeProfitOnFill"] = take_profit
    
    return {"order": order}


def create_limit_order(instrument, units, price, stop_loss=None, take_profit=None):
    """
    Helper function to create a limit order data structure
    
    Parameters
    ----------
    instrument : str
        Instrument symbol (e.g., 'EURUSD')
    units : int
        Positive for BUY, negative for SELL
    price : float
        Limit price
    stop_loss : float, optional
        Stop loss price
    take_profit : float, optional
        Take profit price
    
    Returns
    -------
    dict
        Order data structure
    """
    order = {
        "type": MT4OrderType.LIMIT,
        "instrument": instrument,
        "units": str(units),
        "price": str(price),
        "timeInForce": MT4TimeInForce.GTC
    }
    
    if stop_loss:
        order["stopLossOnFill"] = stop_loss
    if take_profit:
        order["takeProfitOnFill"] = take_profit
    
    return {"order": order}


